#!/usr/bin/env python3
"""按既有报告核对候选连续性，只读取摘要与文件系统元数据。"""
import hashlib
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT / 'scripts'))
from stock_init_data import inspect as inspect_data
from stock_init_metadata_volume import inspect as inspect_metadata


def sha(path):
    with path.open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()


def main():
    work = ROOT / 'work/native-linux-nce'
    initial_path = Path('/Users/fan/project/github.com/iola1999/DroidOnDarwin/work/native-linux-nce/sdk-metadata-disks-v1/initial.json')
    initial = json.loads(initial_path.read_text())
    result = {'scope': 'sdk_metadata_candidate_hash_and_generation_continuity',
              'initial': {'path': str(initial_path), 'sha256': sha(initial_path)},
              'source_disks': [], 'pages': {},
              'sha256': {str(Path(__file__).relative_to(ROOT)): sha(Path(__file__)),
                         'scripts/stock_init_data.py': sha(ROOT / 'scripts/stock_init_data.py'),
                         'scripts/stock_init_metadata_volume.py': sha(ROOT / 'scripts/stock_init_metadata_volume.py')}}
    source_paths = {}
    for candidate in initial['candidates']:
        source = Path(candidate['source'])
        source_paths[source] = candidate['source_sha256']
    for source, expected in source_paths.items():
        observed = sha(source)
        assert observed == expected, str(source)
        result['source_disks'].append({'path': str(source), 'sha256': observed, 'unchanged': True})
    for page in ('4k', '16k'):
        candidates = {row['kind']: row for row in initial['candidates'] if row['page'] == page}
        previous_sha = {kind: row['initial_sha256'] for kind, row in candidates.items()}
        previous_generation = {'data': None, 'metadata': 0}
        page_result = {'runs': [], 'summary_sources': [], 'initial_generation': {}, 'final': {}}
        metadata_initial = inspect_metadata(Path(candidates['metadata']['source']))
        fixed_keys = ('bytes', 'block_bytes', 'filesystem_bytes', 'uuid', 'partition',
                      'gpt_prefix_sha256', 'gpt_suffix_sha256')
        for version in (1, 2, 3):
            source = work / f'sdk-metadata-init-{page}-v{version}/summary.json'
            report = json.loads(source.read_text())
            page_result['summary_sources'].append({'path': str(source), 'sha256': sha(source)})
            for run in report['runs']:
                row = {'version': version, 'entry': run['entry'], 'phase': run['phase'],
                       'returncode': run['returncode'], 'observation_validated': run['observation_validated']}
                for kind in ('data', 'metadata'):
                    before, after = run[kind + '_before'], run[kind + '_after']
                    assert before['path'] == after['path'] == candidates[kind]['path']
                    assert before['sha256'] == previous_sha[kind]
                    generation_rows = [r for r in run['results'] if r.get('stock_init_' + kind + '_generation') is True]
                    assert len(generation_rows) == 1
                    generation = generation_rows[0]
                    if previous_generation[kind] is None:
                        previous_generation[kind] = generation['previous']
                    page_result['initial_generation'].setdefault(kind, previous_generation[kind])
                    assert generation['previous'] == previous_generation[kind]
                    assert generation['generation'] == generation['previous'] + 1
                    assert generation['file_fsync'] == generation['directory_fsync'] == 0
                    assert generation['inherited_fd_closed'] is True
                    if kind == 'metadata':
                        for snapshot in (before, after):
                            assert all(snapshot[key] == metadata_initial[key] for key in fixed_keys)
                    row[kind] = {'before_sha256': before['sha256'], 'after_sha256': after['sha256'],
                                 'previous_generation': generation['previous'], 'generation': generation['generation'],
                                 'clean_after': after['clean'], 'needs_recovery_after': after['needs_recovery']}
                    previous_sha[kind] = after['sha256']
                    previous_generation[kind] = generation['generation']
                page_result['runs'].append(row)
        for kind, inspector in (('data', inspect_data), ('metadata', inspect_metadata)):
            final = inspector(Path(candidates[kind]['path']))
            assert final['sha256'] == previous_sha[kind] and final['clean'] is True
            assert final['needs_recovery'] is False and final['orphan_present'] is False
            page_result['final'][kind] = {**final, 'generation': previous_generation[kind]}
        assert len(page_result['runs']) == 15 and previous_generation['metadata'] == 15
        page_result['continuous'] = True
        result['pages'][page] = page_result
    result['passed'] = True
    target = Path(__file__).with_name('result.json')
    target.write_text(json.dumps(result, indent=2) + '\n')
    print(json.dumps({'passed': True, 'output': str(target),
                      'pages': {page: {'runs': len(row['runs']), 'initial': row['initial_generation'],
                                       'final_generation': {kind: final['generation'] for kind, final in row['final'].items()}}
                                for page, row in result['pages'].items()}}))


if __name__ == '__main__':
    main()

