                 sscanf(size_text, "%llu", &sectors) == 1 && sscanf(ro_text, "%u", &sysfs_ro) == 1;
    REQUIRE(snprintf(sysfs, sizeof(sysfs), "/sys/class/block/ncedisk%up1/partition", slot) < (int)sizeof(sysfs));
    char partition_text[32] = {0};
    long partition_result = raw_erofs_text(sysfs, partition_text, sizeof(partition_text));
    int host_writable = nce_lkl_host.disk_writable(slot);
    printf("{\"raw_erofs_device\":true,\"name\":\"%s\",\"slot\":%u,\"dev_read\":%ld,\"size_read\":%ld,\"ro_read\":%ld,\"major\":%u,\"minor\":%u,\"sectors\":%llu,\"sysfs_ro\":%u,\"host_writable\":%d,\"first_partition_result\":%ld}\n",
           name, slot, dev_read, size_read, ro_read, major, minor, sectors, sysfs_ro, host_writable, partition_result);
    if (!parsed || !major || major >= 4096 || minor != slot || sectors != expected_bytes / 512 ||
        sysfs_ro != 1 || host_writable != 0 || partition_result != -2)
        return 1;

    /* mknodat 接受 Linux new_encode_dev；日志使用 major<<32|minor。 */
    unsigned encoded = (minor & 0xff) | (major << 8) | ((minor & ~0xff) << 12);
    uint64_t device = ((uint64_t)major << 32) | minor;
    long create[6] = {-100, (long)node, 0060600, encoded};
    long node_create = call(33, create);
    struct raw_erofs_status node_status = {0};
    long node_stat = raw_erofs_stat(-100, node, &node_status);
    long open[6] = {-100, (long)node, 0x80000};
    long block_fd = call(56, open);
    int block_ro = -1;
    unsigned long long block_bytes = 0;
    long ioctl[6] = {block_fd, 0x125e, (long)&block_ro};
    long ro_result = call(29, ioctl);
    ioctl[1] = 0x80081272;
    ioctl[2] = (long)&block_bytes;
    long size_result = call(29, ioctl);
    long close[6] = {block_fd};
    long block_close = call(57, close);
    long block_write_open = -1, block_write_result = -1, block_write_close = -1;
    int block_write_attempted = 0, block_write_host_writable = -1;
    if (!node_create && !node_stat && block_ro == 1 && !ro_result) {
        open[2] = 0x80001;
        block_write_open = call(56, open);
        if (block_write_open >= 0) {
            /* host 文件仍以 O_RDONLY 打开；Linux write_iter 在只读盘返回 -EPERM。 */
            block_write_host_writable = nce_lkl_host.disk_writable(slot);
            if (!block_write_host_writable) {
                unsigned char zero[512] = {0};
                long write[6] = {block_write_open, (long)zero, sizeof(zero)};
                block_write_attempted = 1;
                block_write_result = call(64, write);
            }
            close[0] = block_write_open;
            block_write_close = call(57, close);
        }
    }
    printf("{\"raw_erofs_node\":true,\"name\":\"%s\",\"node_create\":%ld,\"node_stat\":%ld,\"node_mode\":%u,\"node_rdev\":%llu,\"block_fd\":%ld,\"ro_result\":%ld,\"block_ro\":%d,\"size_result\":%ld,\"block_bytes\":%llu,\"block_close\":%ld,\"block_write_attempted\":%s,\"block_write_host_writable\":%d,\"block_write_bytes\":512,\"block_write_open\":%ld,\"block_write_result\":%ld,\"block_write_close\":%ld}\n",
           name, node_create, node_stat, node_status.mode, (unsigned long long)node_status.rdev, block_fd,
           ro_result, block_ro, size_result, block_bytes, block_close, block_write_attempted ? "true" : "false",
           block_write_host_writable, block_write_open, block_write_result, block_write_close);
    if (node_create || node_stat || (node_status.mode & 0170000) != 0060000 || node_status.rdev != device ||
        block_fd < 0 || ro_result || block_ro != 1 || size_result || block_bytes != expected_bytes || block_close ||
        !block_write_attempted || block_write_host_writable || block_write_open < 0 || block_write_result != -1 || block_write_close)
        return 1;

    long mount[6] = {(long)node, (long)target, (long)"erofs", 1};
    long mount_result = call(40, mount);
    printf("{\"raw_erofs_mount\":true,\"name\":\"%s\",\"result\":%ld,\"flags\":1}\n", name, mount_result);
    if (mount_result)
        return 1;
    open[1] = (long)target;
    open[2] = 0x84000;
    long root_fd = call(56, open);
    /* 固定 Linux arm64 statfs ABI 为 120 bytes，f_flags 位于 byte 80。 */
    long filesystem[15] = {0};
    long statfs[6] = {root_fd, (long)filesystem};
    long filesystem_result = call(44, statfs);
    struct raw_erofs_status root = {0};
    long root_result = raw_erofs_stat(root_fd, "", &root);
    long file_write = -1;
    int file_write_attempted = root_fd >= 0 && !filesystem_result && filesystem[0] == 0xe0f5e1e2UL && (filesystem[10] & 1);
    if (file_write_attempted) {
        long write_open[6] = {-100, (long)write_path, 0x800c1, 0600};
        file_write = call(56, write_open);
        if (file_write >= 0) {
            close[0] = file_write;
            REQUIRE(call(57, close) == 0);
        }
    }
    printf("{\"raw_erofs_root\":true,\"name\":\"%s\",\"root_fd\":%ld,\"filesystem_result\":%ld,\"filesystem_type\":%lu,\"filesystem_flags\":%lu,\"stat_result\":%ld,\"device\":%llu,\"rdev\":%llu,\"mode\":%u,\"uid\":%u,\"gid\":%u,\"file_write_attempted\":%s,\"file_write_open\":%ld}\n",
           name, root_fd, filesystem_result, (unsigned long)filesystem[0], (unsigned long)filesystem[10], root_result,
           (unsigned long long)root.device, (unsigned long long)root.rdev, root.mode, root.uid, root.gid,
           file_write_attempted ? "true" : "false", file_write);
    close[0] = root_fd;
    long root_close = call(57, close);
    long unmount[6] = {(long)target, 0};
    long unmount_result = call(39, unmount);
    printf("{\"raw_erofs_cleanup\":true,\"name\":\"%s\",\"root_close\":%ld,\"unmount_result\":%ld}\n", name, root_close, unmount_result);
    int passed = root_fd >= 0 && !filesystem_result && filesystem[0] == 0xe0f5e1e2UL && (filesystem[10] & 1) &&
                 !root_result && root.device == device && !root.rdev && root.mode == (0040000 | expected_mode) &&
                 root.uid == expected_uid && root.gid == expected_gid && file_write_attempted && file_write == -30 &&
                 !root_close && !unmount_result;
    printf("{\"test\":\"raw_erofs_whole_disk_readonly\",\"name\":\"%s\",\"slot\":%u,\"passed\":%s}\n", name, slot, passed ? "true" : "false");
    return !passed;
}

#!/usr/bin/env python3
"""从固定 core 命令生成两页独立的只读 raw EROFS probe。"""
import hashlib
import json
from pathlib import Path
import subprocess

COMMON = Path(__file__).resolve().parent
ROOT = COMMON.parents[2]
MAIN = ROOT.parents[1]


def digest(path):
    with Path(path).open('rb') as source:
        return hashlib.file_digest(source, 'sha256').hexdigest()


def write(path, data):
    with Path(path).open('x') as target:
        json.dump(data, target, indent=2, ensure_ascii=False)
        target.write('\n')


manifest_path = MAIN / 'work/continue-hyperos-jit/work/native-linux-nce/hyperos-init-input-v6/manifest.json'
manifest = json.loads(manifest_path.read_text())
if digest(manifest_path) != '1ece2c7f87a9064a28a823309476d10044a795bad25b887e5e07a8859137ad06':
    raise RuntimeError('fixed manifest changed')
inputs = {}
for name, slot in [('vendor', 2), ('system_dlkm', 3)]:
    image = manifest['images'][name]
    path = Path(image['path'])
    if not path.is_file() or path.stat().st_size != image['bytes'] or digest(path) != image['sha256']:
        raise RuntimeError(f'fixed raw EROFS changed: {name}')
    metadata = manifest['vendor_directories_metadata']['/vendor'] if name == 'vendor' else manifest['system_dlkm_root_metadata']
    inputs[name] = {**image, 'slot': slot, 'writable': 0,
                    'root': {key: metadata[key] for key in ('mode', 'uid', 'gid')}}

source = ROOT / 'experiments/native-linux/translation/linux-runner.c'
runner = COMMON / 'linux-runner.c'
if runner.exists():
    raise RuntimeError('private source already exists')
subprocess.run(['cp', '-c', str(source), str(runner)], check=True, timeout=30)
text = runner.read_text()


def replace(old, new):
    global text
    if text.count(old) != 1:
        raise RuntimeError(f'private patch anchor count: {text.count(old)}')
    text = text.replace(old, new)


replace('static void android_setup(int services, int desktop)\n',
        '#include "raw-erofs-probe.h"\n\nstatic void android_setup(int services, int desktop)\n')
open_source = '    REQUIRE(!android && !stock_art && !stock_bionic);\n'
for name, slot in [('vendor', 2), ('system_dlkm', 3)]:
    open_source += f'    REQUIRE(nce_disk_open({slot}, {json.dumps(inputs[name]["path"])}, 0) == 0);\n'
replace('''    if (android) {
        REQUIRE(getenv("NCE_TRANSLATION_SYSTEM"));
        REQUIRE(nce_disk_open(1, getenv("NCE_TRANSLATION_SYSTEM"), 0) == 0);
        if (services) {
            REQUIRE(getenv("NCE_TRANSLATION_DATA"));
            REQUIRE(nce_disk_open(0, getenv("NCE_TRANSLATION_DATA"), 1) == 0);
        }
    }
''', open_source)
checks = '''    int failed = 0;
    directory("/dev");
    directory("/sys");
    long raw_sysfs_mount[6] = {(long)"sysfs", (long)"/sys", (long)"sysfs"};
    long raw_sysfs_result = call(40, raw_sysfs_mount);
    printf("{\\\"raw_erofs_sysfs_mount\\\":true,\\\"result\\\":%ld}\\n", raw_sysfs_result);
    if (!raw_sysfs_result) {
'''
for name, slot in [('vendor', 2), ('system_dlkm', 3)]:
    image = inputs[name]
    if name == 'system_dlkm':
        checks += '        if (!failed)\n'
    checks += f'        failed |= raw_erofs_check({slot}, "{name}", {image["bytes"]}ULL, {image["root"]["mode"]}, {image["root"]["uid"]}, {image["root"]["gid"]});\n'
checks += '''        long raw_sysfs_unmount[6] = {(long)"/sys", 0};
        long raw_sysfs_removed = call(39, raw_sysfs_unmount);
        printf("{\\\"raw_erofs_sysfs_cleanup\\\":true,\\\"unmount_result\\\":%ld}\\n", raw_sysfs_removed);
        failed |= raw_sysfs_removed != 0;
    } else {
        failed = 1;
    }
    if (failed)
        goto raw_probe_cleanup;
'''
replace('    int failed = 0;\n', checks)
replace('        failed = run_program("/probe-guest", 0);\n', '        failed |= run_program("/probe-guest", 0);\n')
replace('    if (TRANSLATION_LOOKUP && !android && !stock_bionic && !stock_art) {\n        REQUIRE(host_value == 0x7d2a9314UL);\n',
        'raw_probe_cleanup:\n    if (TRANSLATION_LOOKUP && !android && !stock_bionic && !stock_art) {\n        REQUIRE(host_value == 0x7d2a9314UL);\n')
replace('    REQUIRE(halt() == 0);\n', '    int raw_halt_result = halt();\n    REQUIRE(raw_halt_result == 0);\n')
replace('    REQUIRE(translation_kernel_release(&loaded) == 0);\n',
        '''    int raw_release_result = translation_kernel_release(&loaded);
    REQUIRE(raw_release_result == 0);
    printf("{\\\"raw_erofs_standard_shutdown\\\":true,\\\"halt_result\\\":%d,\\\"disk_close_result\\\":%d,\\\"kernel_release_result\\\":%d}\\n", raw_halt_result, disk_close_result, raw_release_result);
''')
runner.write_text(text)
subprocess.run(['/opt/homebrew/opt/llvm/bin/clang-format', '-i', str(runner), str(COMMON / 'raw-erofs-probe.h')],
               check=True, timeout=30)

clones = [{'source': str(source), 'target': str(runner), 'command': ['cp', '-c', str(source), str(runner)],
           'source_sha256': digest(source), 'private_sha256': digest(runner), 'source_bytes': source.stat().st_size}]
for page in ['4k', '16k']:
    core = ROOT / 'work/native-linux-nce' / f'sdk-metadata-core-{page}-v1/summary.json'
    report = json.loads(core.read_text())
    for name, expected in report['sha256'].items():
        if digest(ROOT / name) != expected:
            raise RuntimeError(f'core source changed: {name}')
    output = ROOT / 'work/native-linux-nce' / f'sdk-metadata-raw-erofs-{page}-v2'
    if any(output.iterdir()):
        raise RuntimeError(f'output already populated: {output}')
    commands = []
    fixed = dict(report['sha256'])
    fixed[str(core.relative_to(ROOT))] = digest(core)
    for original in report['commands'][:2]:
        command = [str(runner) if token == str(source) else token for token in original]
        index = command.index('-o') + 1
        entry = Path(command[index]).name
        command[index] = str(output / entry)
        command += ['-I', str(ROOT / 'experiments/native-linux/translation'), '-I', str(COMMON)]
        commands.append({'entry': entry, 'command': command})
        for token in original:
            path = Path(token)
            if path.is_absolute() and path.is_file() and path.suffix in ('.o', '.a'):
                fixed[str(path.relative_to(ROOT))] = digest(path)
    for path in [runner, COMMON / 'raw-erofs-probe.h', COMMON / 'prepare.py', COMMON / 'execute.py', COMMON / 'raw_erofs_validation.py']:
        fixed[str(path.relative_to(ROOT))] = digest(path)
    write(output / 'invocation.json', {'scope': 'fixed HyperOS-AVD ranchu raw EROFS whole-disk readonly mount; original init not run',
                                     'page': page, 'core': str(core), 'core_sha256': digest(core),
                                     'configuration': report['configuration'], 'manifest': str(manifest_path),
                                     'manifest_sha256': digest(manifest_path), 'raw_inputs': inputs,
                                     'commands': commands, 'fixed_sha256': fixed})
write(COMMON / 'preparation.json', {'raw_inputs': inputs, 'manifest': str(manifest_path),
                                  'manifest_sha256': digest(manifest_path), 'clones': clones,
                                  'private_runner_sha256': digest(runner), 'private_header_sha256': digest(COMMON / 'raw-erofs-probe.h')})
write(ROOT / 'work/cleanup-2026-11-13/sdk-metadata-raw-erofs-v2-runner-clone.json',
      {'clones': clones, 'raw_image_copies': [], 'retained_for_review': [str(COMMON)]})
print(json.dumps({'prepared': True, 'pages': ['4k', '16k'], 'input_copies': 0, 'private_runner_sha256': digest(runner)}))
